BEGIN;
CREATE TABLE ledger_private.trivia_packs(game text NOT NULL,slot integer NOT NULL CHECK(slot BETWEEN 0 AND 13),version integer NOT NULL,questions jsonb NOT NULL,PRIMARY KEY(game,slot,version));
CREATE TABLE ledger_private.trivia_attempts(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),player text NOT NULL CHECK(player IN ('michal','rina','ohm','rohil')),game text NOT NULL,day date NOT NULL,slot integer NOT NULL,version integer NOT NULL DEFAULT 1,answers jsonb NOT NULL DEFAULT '[]',hints jsonb NOT NULL DEFAULT '{}',score integer NOT NULL DEFAULT 0 CHECK(score BETWEEN 0 AND 1000),UNIQUE(player,game,day),FOREIGN KEY(game,slot,version) REFERENCES ledger_private.trivia_packs);
ALTER TABLE ledger_private.trivia_packs ENABLE ROW LEVEL SECURITY;
ALTER TABLE ledger_private.trivia_attempts ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON ledger_private.trivia_packs,ledger_private.trivia_attempts FROM PUBLIC,anon,authenticated;
CREATE FUNCTION ledger_private.trivia_normalize(value text) RETURNS text LANGUAGE sql IMMUTABLE SET search_path='' AS $$
 SELECT regexp_replace(lower(translate(value,'ÀÁÂÃÄÅàáâãäåÈÉÊËèéêëÌÍÎÏìíîïÒÓÔÕÖòóôõöÙÚÛÜùúûüÇçÑñ','AAAAAAaaaaaaEEEEeeeeIIIIiiiiOOOOOoooooUUUUuuuuCcNn')),'[^a-z0-9]','','g');
$$;
CREATE FUNCTION ledger_private.trivia_state(a ledger_private.trivia_attempts) RETURNS jsonb LANGUAGE plpgsql STABLE SET search_path='' AS $$
DECLARE pack jsonb;q jsonb;qs jsonb:='[]';i integer:=0;level integer;
BEGIN
 SELECT questions INTO pack FROM ledger_private.trivia_packs WHERE game=a.game AND slot=a.slot AND version=a.version;
 FOR q IN SELECT value FROM jsonb_array_elements(pack) LOOP
  level:=coalesce((a.hints->>i::text)::integer,0);
  IF i>=jsonb_array_length(a.answers) THEN
   q:=q-'answer'-'aliases'-'explanation'-'sources';
   IF q->>'kind'='clues' THEN q:=jsonb_set(q,'{clues}',(SELECT jsonb_agg(value ORDER BY ordinality) FROM jsonb_array_elements(q->'clues') WITH ORDINALITY WHERE ordinality<=level+1));END IF;
  END IF;
  qs:=qs||jsonb_build_array(q);i:=i+1;
 END LOOP;
 RETURN to_jsonb(a)||jsonb_build_object('questions',qs,'complete',jsonb_array_length(a.answers)=jsonb_array_length(pack) OR a.day<(now() AT TIME ZONE 'America/New_York')::date,'server_day',(now() AT TIME ZONE 'America/New_York')::date);
END;$$;
CREATE FUNCTION public.utilities_trivia_start(p jsonb) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$
DECLARE a ledger_private.trivia_attempts;d date:=(now() AT TIME ZONE 'America/New_York')::date;s integer;
BEGIN
 IF coalesce(p->>'player','') NOT IN ('michal','rina','ohm','rohil') THEN RAISE EXCEPTION 'Choose a household player for Daily';END IF;
 s:=((d-DATE '2026-11-09')%14+14)%14;
 IF NOT EXISTS(SELECT 1 FROM ledger_private.trivia_packs WHERE game=p->>'game' AND slot=s AND version=1) THEN RAISE EXCEPTION 'Unknown game';END IF;
 INSERT INTO ledger_private.trivia_attempts(player,game,day,slot) VALUES(p->>'player',p->>'game',d,s) ON CONFLICT(player,game,day) DO NOTHING;
 SELECT * INTO a FROM ledger_private.trivia_attempts WHERE player=p->>'player' AND game=p->>'game' AND day=d;
 RETURN ledger_private.trivia_state(a);
END;$$;
CREATE FUNCTION public.utilities_trivia_action(p jsonb) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$
DECLARE a ledger_private.trivia_attempts;q jsonb;pack jsonb;idx integer;level integer;points integer:=0;ratio numeric;guess jsonb;correct boolean;i integer;j integer;
BEGIN
 SELECT * INTO a FROM ledger_private.trivia_attempts WHERE id=(p->>'id')::uuid AND player=p->>'player' FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION 'Attempt unavailable';END IF;
 idx:=(p->>'index')::integer;
 IF idx IS NULL OR idx<0 THEN RAISE EXCEPTION 'Invalid question';END IF;
 -- A repeated answer is idempotent; conflicting writes cannot replace it.
 IF idx<jsonb_array_length(a.answers) THEN
  IF p->>'action'='answer' AND a.answers->idx->'value' IS DISTINCT FROM p->'answer' THEN RAISE EXCEPTION 'This answer is already locked';END IF;
  RETURN ledger_private.trivia_state(a);
 END IF;
 IF a.day<>(now() AT TIME ZONE 'America/New_York')::date THEN RAISE EXCEPTION 'This daily round has ended';END IF;
 SELECT questions INTO pack FROM ledger_private.trivia_packs WHERE game=a.game AND slot=a.slot AND version=a.version;
 IF idx<>jsonb_array_length(a.answers) OR idx>=jsonb_array_length(pack) THEN RAISE EXCEPTION 'Resume the current question';END IF;
 q:=pack->idx;level:=coalesce((a.hints->>idx::text)::integer,0);
 IF p->>'action'='clue' THEN
  IF q->>'kind'<>'clues' OR (p->>'level')::integer NOT BETWEEN 1 AND 3 OR (p->>'level')::integer>level+1 OR p->>'level' IS NULL THEN RAISE EXCEPTION 'Invalid clue request';END IF;
  UPDATE ledger_private.trivia_attempts SET hints=jsonb_set(hints,ARRAY[idx::text],to_jsonb(greatest(level,(p->>'level')::integer))) WHERE id=a.id RETURNING * INTO a;
 ELSIF p->>'action'='answer' THEN
  guess:=p->'answer';
  IF guess IS NULL OR length(guess::text)>2000 THEN RAISE EXCEPTION 'Answer required';END IF;
  CASE q->>'kind'
  WHEN 'choice' THEN
   IF NOT (q->'options' @> jsonb_build_array(guess)) THEN RAISE EXCEPTION 'Choose an option';END IF;
   IF guess=q->'answer' THEN points:=200;END IF;
  WHEN 'clues' THEN
   IF jsonb_typeof(guess)<>'string' THEN RAISE EXCEPTION 'Enter a name';END IF;
   SELECT EXISTS(SELECT 1 FROM jsonb_array_elements_text(coalesce(q->'aliases','[]')||jsonb_build_array(q->>'answer')) x WHERE ledger_private.trivia_normalize(x)=ledger_private.trivia_normalize(guess#>>'{}')) INTO correct;
   IF correct THEN points:=200-50*level;END IF;
  WHEN 'scale' THEN
   IF jsonb_typeof(guess)<>'number' THEN RAISE EXCEPTION 'Enter a ratio';END IF;
   ratio:=(guess#>>'{}')::numeric;
   IF ratio<(q->'bounds'->>0)::numeric OR ratio>(q->'bounds'->>1)::numeric THEN RAISE EXCEPTION 'Ratio outside scale';END IF;
   points:=round(200*least(ratio/(q->>'answer')::numeric,(q->>'answer')::numeric/ratio));
  WHEN 'timeline' THEN
   IF jsonb_typeof(guess)<>'array' OR jsonb_array_length(guess)<>5 THEN RAISE EXCEPTION 'Arrange all five cards';END IF;
   IF (SELECT count(DISTINCT value) FROM jsonb_array_elements_text(guess))<>5 OR NOT (guess <@ (q->'answer')) THEN RAISE EXCEPTION 'Invalid timeline';END IF;
   FOR i IN 0..3 LOOP FOR j IN i+1..4 LOOP
    IF (SELECT ordinality FROM jsonb_array_elements(q->'answer') WITH ORDINALITY WHERE value=(guess->i))<(SELECT ordinality FROM jsonb_array_elements(q->'answer') WITH ORDINALITY WHERE value=(guess->j)) THEN points:=points+100;END IF;
   END LOOP;END LOOP;
  ELSE RAISE EXCEPTION 'Unknown question type';END CASE;
  UPDATE ledger_private.trivia_attempts SET answers=answers||jsonb_build_array(jsonb_build_object('value',guess,'points',points)),score=score+points WHERE id=a.id RETURNING * INTO a;
 ELSE RAISE EXCEPTION 'Unknown action';END IF;
 RETURN ledger_private.trivia_state(a);
END;$$;
CREATE FUNCTION ledger_private.trivia_standings(p jsonb,at_day date) RETURNS jsonb LANGUAGE sql STABLE SET search_path='' AS $$
 WITH clock AS(SELECT at_day AS today),daily AS(
 SELECT a.*,row_number() OVER(PARTITION BY player ORDER BY score DESC,day DESC) AS n
 FROM ledger_private.trivia_attempts a JOIN ledger_private.trivia_packs c USING(game,slot,version),clock
 WHERE a.game=p->>'game' AND a.day BETWEEN CASE WHEN p->>'period'='week' THEN date_trunc('week',today::timestamp)::date ELSE today END AND today
 AND (a.day<today OR jsonb_array_length(a.answers)=jsonb_array_length(c.questions))
 ), totals AS(SELECT player,sum(score)::integer AS score,count(*) AS days FROM daily WHERE n<=5 GROUP BY player),ranked AS(SELECT *,rank() OVER(ORDER BY score DESC)::integer AS rank FROM totals)
 SELECT coalesce(jsonb_agg(to_jsonb(ranked) ORDER BY rank,player),'[]') FROM ranked;
$$;
CREATE FUNCTION public.utilities_trivia_scores(p jsonb) RETURNS jsonb LANGUAGE sql STABLE SECURITY DEFINER SET search_path='' AS $$ SELECT ledger_private.trivia_standings(p,(now() AT TIME ZONE 'America/New_York')::date);$$;
CREATE FUNCTION public.utilities_trivia_export(p jsonb) RETURNS jsonb LANGUAGE sql STABLE SECURITY DEFINER SET search_path='' AS $$
 SELECT coalesce(jsonb_agg(to_jsonb(a) ORDER BY day,game),'[]') FROM ledger_private.trivia_attempts a WHERE player=p->>'player';
$$;
CREATE FUNCTION public.utilities_trivia_capabilities() RETURNS jsonb LANGUAGE sql IMMUTABLE SET search_path='' AS $$ SELECT '{"version":1,"games":5,"daily_packs":14}'::jsonb;$$;
REVOKE ALL ON FUNCTION public.utilities_trivia_start(jsonb),public.utilities_trivia_action(jsonb),public.utilities_trivia_scores(jsonb),public.utilities_trivia_export(jsonb),public.utilities_trivia_capabilities() FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.utilities_trivia_start(jsonb),public.utilities_trivia_action(jsonb),public.utilities_trivia_scores(jsonb),public.utilities_trivia_export(jsonb),public.utilities_trivia_capabilities() TO anon,authenticated,service_role;
